"""Build bounded P4 cross/FFN math with the pinned Hike toolchain."""
import hashlib,json,os,re,subprocess
from pathlib import Path
r=Path(__file__).resolve().parent;t=Path(os.environ['DIFFUSION_TOOLCHAIN']).resolve();sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();p=json.loads((t/'provenance.json').read_text())
assert p['hikeCommit']=='3c51fde6675f317453919bd505d0e2d0f638e7f1';assert sha(t/'hikec')=='fb4588cba306b8dded91ad02735254681eaca08fa997f55919185cd607e89b26'
command=[str(t/'hikec'),'build','-target','wabt','-wasm-mode','normal','-o',str(r/'kernel.wasm'),str(r/'math.hike')]
env=dict(os.environ,PATH=str(t/'wabt/node_modules/.bin')+os.pathsep+os.environ['PATH']);run=subprocess.run(command,env=env,capture_output=True,text=True);(r/'build.log').write_text(run.stdout+run.stderr);run.check_returncode()
runtime=r/'runtime.js';runtime.write_text('\n'.join(line.rstrip() for line in runtime.read_text().splitlines()).rstrip()+'\n')
subprocess.run(['node',str(t/'wabt/node_modules/wabt/bin/wasm2wat'),str(r/'kernel.wasm'),'-o',str(r/'kernel.wat')],check=True);wat=(r/'kernel.wat').read_text()
imports={'sqrt':'f64','tanh':'f64'};assert set(re.findall(r'\(import "env" "([^"]+)"',wat))==set(imports)
for name,signature in imports.items():
 m=re.search(r'\(import "env" "'+name+r'" \(func \(;\d+;\) \(type (\d+)\)\)\)',wat);assert m,name
 assert re.search(r'\(type \(;'+m[1]+r';\) \(func \(param '+signature+r'\) \(result f64\)\)\)',wat),name
abi={'Norm':'i32 i32 i32 i32 i32 i32','Gelu':'i32 i32 i32 i32','Add':'i32 i32 i32 i32 i32','Modulate':'i32 i32 i32 i32 i32','GateResidual':'i32 i32 i32 i32 i32 i32'}
for name,signature in abi.items():
 idx=re.search(r'\(export "'+name+r'" \(func (\d+)\)\)',wat)[1];assert re.search(r'\(func \(;'+idx+r';\) \(type \d+\) \(param '+signature+r'\) \(result i32\)',wat),name
assert 'f32.mul' in wat and 'f32.add' in wat and 'f32.sub' in wat and 'f32.div' in wat
h=sha(r/'kernel.wasm');(r/'registry.mjs').write_text('// Generated by post-self-attention/build.py\nexport const POST_SELF_ATTENTION_MATH_SHA256='+json.dumps(h)+';\n')
record={'hikeCommit':p['hikeCommit'],'compilerSha256':sha(t/'hikec'),'backend':'wabt','mode':'normal','sourceSha256':sha(r/'math.hike'),'sourceBytes':(r/'math.hike').stat().st_size,'hostSha256':sha(r/'math.mjs'),'hostBytes':(r/'math.mjs').stat().st_size,'builderSha256':sha(Path(__file__)),'builderBytes':Path(__file__).stat().st_size,'wasmSha256':h,'wasmBytes':(r/'kernel.wasm').stat().st_size,'watSha256':sha(r/'kernel.wat'),'runtimeSha256':sha(runtime),'imports':[{'module':'env','name':name,'signature':signature+' -> f64','bridge':'fixed ECMAScript Math.'+name} for name,signature in imports.items()],'abi':abi,'command':command,'versions':p['versions'],'scope':'P4 full5120 nonaffine/affine LayerNorm and affine RMSNorm epsilon1e-6; tanh GELU bounded27648; N2 modulation/add/gated cross residual; F32 separate multiply/add diagnostic, not GPU precision parity or full model'}
(r/'build-record.json').write_text(json.dumps(record,indent=2)+'\n');print(json.dumps({'wasmSha256':h,'bytes':(r/'kernel.wasm').stat().st_size}))
